using MallEnergyBilling.Web.Models;namespace MallEnergyBilling.Web.Services;
public sealed record BillingInput(decimal Opening,decimal Closing,decimal Tariff,decimal Fixed,decimal Other,decimal TaxPercent,decimal Discount,decimal PreviousBalance);public sealed record BillingResult(decimal Consumption,decimal EnergyCharge,decimal Tax,decimal Total);
public sealed class BillingCalculator{public BillingResult Calculate(BillingInput x){if(x.Closing<x.Opening)throw new InvalidOperationException("Closing reading cannot be below opening reading; review required.");var c=x.Closing-x.Opening;var e=decimal.Round(c*x.Tariff,2,MidpointRounding.AwayFromZero);var taxable=e+x.Fixed+x.Other;var tax=decimal.Round(taxable*x.TaxPercent/100m,2,MidpointRounding.AwayFromZero);return new(c,e,tax,decimal.Round(taxable+tax-x.Discount+x.PreviousBalance,2,MidpointRounding.AwayFromZero));}}
public static class ModbusConverter{public static uint UInt32(ushort first,ushort second,WordOrder order)=>order==WordOrder.HighLow?((uint)first<<16)|second:((uint)second<<16)|first;public static decimal Scale(ulong raw,decimal factor)=>raw*factor;}
